--   Director (Division 6): Audrey T. Miller -- appointed 2024-12-01 (month)
--   Director (Division 7): Gary Van Dam -- appointed 2024-12-01 (month)
-- Palmdale Water District (by division, 5 seats; RR/CC DST IRR PA; https://www.palmdalewater.org/governance/board-of-directors/):
--   Director (Division 1): Scott Kellerman -- appointed 2024-12-01 (month)
--   Director (Division 2): Don Wilson -- elected 2022-12-01 (month)
--   Director (Division 3): Cynthia Sanchez -- elected 2024-12-01 (month) [reused row e18c2e6e]
--   Director (Division 4): Kathy Mac Laren-Gomez -- elected 2024-12-01 (month)
--   Director (Division 5): Debbie Dino -- appointed 2025-08-01 (month)
-- Santa Clarita Valley Water Agency (by division, 9 seats; RR/CC DST WAG SC; https://www.yourscvwater.com/governance/board-directors):
--   Director (Division 1): Bill Cooper -- elected 2023-01-01 (month) [reused row ee381f84]
--   Director (Division 1): Gary R. Martin -- elected 2025-01-01 (month)
--   Director (Division 1): Dan Masnada -- elected 2025-01-01 (month)
--   Director (Division 2): Dirk S. Marks -- elected 2023-01-01 (month)
--   Director (Division 2): Ken Cooper -- elected 2025-01-01 (month) [reused row 881d5e85]
--   Director (Division 2): Piotr Orzechowski -- elected 2025-01-01 (month) [reused row 4d4f85a7]
--   Director (Division 3): Maria Gutzeit -- elected 2023-01-01 (month)
--   Director (Division 3): Kenneth J. Petersen -- elected 2025-01-01 (month)
--   Director (Division 3): Kathye Armitage -- elected 2025-01-01 (month)
--
-- BATCH NOTES:
--   ON THE BALLOT (12 races / 25 candidates): Foothill Div 2, Div 4, Div 5 (OPEN: Colcord did not file); Las Virgenes
--     Div 2; Walnut Valley Div 2 (OPEN: Hilden did not file), Div 3, and a Div 5 SPECIAL for the unexpired term to Dec
--     2028; AVEK Div 1 and Div 3; Palmdale WD Div 2 (OPEN: Wilson did not file); SCV Water Div 1 (1 seat) and Div 3 (2
--     seats: Gutzeit's four-year seat and Petersen's 2024 two-year seat).
--   APPOINTED IN LIEU (no race): Las Virgenes Div 3 (Burns) and Div 5 (Lewitt); Rowland Div 3, 4, 5 -- RR/CC Notice of
--     No Election 2026-08-26 (rwd.org/wp-content/uploads/2026/08/Exibit-E-NOTICE-OF-NO-ELECTION-Rowland-County-Water-
--     District-.pdf); AVEK Div 5 (sole nominee Daniel P. Jacobs; Parris did not file; Parris stays seated until December)
--     -- RR/CC notice avek.org/files/679d90c21/26.08.18-Notice-of-Election-No-Election-and-List-of-Candidates.pdf;
--     Palmdale Div 5 (Dino); SCV Water Div 2 (Marks) -- RR/CC notice on yourscvwater.com.
--   AVEK: the LA precinct layer carries AVEK Divisions 1 and 3-7 only; Division 2 (Keith Dyas) lies wholly in Kern
--     County, so it is NOT modeled (it has no LA County geography and would be unreachable). Division 1 also crosses into
--     Kern; only the LA part is drawn.
--   SCV WATER: 9 elected directors, 3 per division (staggered), modeled as 3 offices on each division's district; its
--     appointed seats (retail-agency directors) are not modeled. Its board page is stale (still lists Edward Colley, term
--     expired Jan 2025); the 2024 Div 2 winners Ken Cooper and Piotr Orzechowski hold those seats (RR/CC 4324). Terms
--     start in January.
--   DIVISION CHECK: Foothill 1 west Altadena / 2 east Altadena / 4 La Canada Flintridge / 5 La Crescenta-Montrose;
--     Walnut Valley 1 Walnut / 2 north Diamond Bar / 3 south Diamond Bar / 4 Rowland Heights; Las Virgenes 1 Calabasas
--     (Levine's city) / 4 Westlake Village (Polan's city). Rowland, AVEK, Palmdale, SCV publish map images only. Las
--     Virgenes' map file is dated 2025; the RR/CC layer matches the directors' home cities.
--   REUSED ROWS (2024 NetFile filers, same people): Bill Cooper, Ken Cooper, Piotr Orzechowski, Cynthia Sanchez.
BEGIN;

-- ─── 1. Government + governing board (chamber) per special district (none existed) ─────────
INSERT INTO essentials.governments (id, name, type, state)
SELECT v.id, v.name, 'LOCAL', 'CA'
  FROM (VALUES
    ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, 'Foothill Municipal Water District, California, US'),
    ('50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'Las Virgenes Municipal Water District, California, US'),
    ('df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'Walnut Valley Water District, California, US'),
    ('a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, 'Rowland Water District, California, US'),
    ('4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'Antelope Valley-East Kern Water Agency, California, US'),
    ('ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, 'Palmdale Water District, California, US'),
    ('8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid, 'Santa Clarita Valley Water Agency, California, US')
  ) AS v(id, name)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.governments g WHERE g.id = v.id);

INSERT INTO essentials.chambers (id, government_id, name, name_formal, term_length, election_frequency, website_url, policy_engagement_level)
SELECT v.id, v.gid, v.name, v.name_formal, '4 years', '2 years', v.url, 'full'   -- slug is generated
  FROM (VALUES
    ('29c6fb5e-8ed6-57d1-8ded-960cf14ef6ad'::uuid, 'f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, 'Board of Directors', 'Foothill Municipal Water District Board of Directors', 'https://www.fmwd.com/board-members'),
    ('a4804b9d-21ee-5ee4-92b7-6a38326205ee'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'Board of Directors', 'Las Virgenes Municipal Water District Board of Directors', 'https://www.lvmwd.gov/board-of-directors'),
    ('350d2ea9-1db1-5960-8eb8-eb195b6df833'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'Board of Directors', 'Walnut Valley Water District Board of Directors', 'https://walnutvalleywater.gov/about-us/board-of-directors/'),
    ('6d72d989-ed21-51d3-b9a6-d93a66bf12a3'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, 'Board of Directors', 'Rowland Water District Board of Directors', 'https://rwd.org/governance/'),
    ('2b8e372b-5600-5a93-973e-aa1c5a3ed136'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'Board of Directors', 'Antelope Valley-East Kern Water Agency Board of Directors', 'https://www.avek.org/board-of-directors-995f488'),
    ('c3f3019d-2462-50e4-8ab5-93617f148183'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, 'Board of Directors', 'Palmdale Water District Board of Directors', 'https://www.palmdalewater.org/governance/board-of-directors/'),
    ('0f3f0ace-c00e-5cb0-be1e-a8d82776a933'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid, 'Board of Directors', 'Santa Clarita Valley Water Agency Board of Directors', 'https://www.yourscvwater.com/governance/board-directors')
  ) AS v(id, gid, name, name_formal, url)
 WHERE NOT EXISTS (SELECT 1 FROM essentials.chambers c WHERE c.id = v.id);

