-- ─── 8. Post-verify gate ──────────────────────────────────────────────────────────────────
DO $$
DECLARE n int; n2 int;
BEGIN
  SELECT count(*) INTO n FROM essentials.geofence_boundaries gb
   WHERE gb.mtfcc = 'X-CA-SPD' AND gb.geo_id IN (SELECT d.geo_id FROM essentials.districts d WHERE d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid))
     AND public.ST_IsValid(gb.geometry) AND NOT public.ST_IsEmpty(gb.geometry) AND public.ST_SRID(gb.geometry) = 4326;
  IF n <> 34 THEN RAISE EXCEPTION 'expected 34 valid polygons, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.districts d WHERE d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid) AND d.district_type = 'LOCAL' AND d.mtfcc = 'X-CA-SPD';
  IF n <> 34 THEN RAISE EXCEPTION 'expected 34 LOCAL districts, got %', n; END IF;

  SELECT count(*) INTO n FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id WHERE d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid);
  IF n <> 40 THEN RAISE EXCEPTION 'expected 40 offices, got %', n; END IF;

  -- every held seat is held by exactly the director named for it (office_current_holder = query-time occupant)
  SELECT count(*) INTO n FROM (VALUES ('f3195e82-9666-5a2c-aa71-b77d98b85e36'::uuid, 'd385364f-5adc-5662-b8e9-b64810ed33e6'::uuid), ('7d5d8326-6dfa-54ec-aae4-023a985c3560'::uuid, '6d28a55c-00f1-50e2-b611-5ec83136b0e3'::uuid), ('a1a0d946-d66e-5654-9d82-0f30076842d6'::uuid, 'c8fe09b8-2d92-5512-843a-334652245540'::uuid), ('b9ae0830-b8e4-5f3c-8bdf-0e90bcd64fa6'::uuid, 'efdbb389-d789-5873-a2ca-2b83c71fe473'::uuid), ('a1ff23fb-dfe2-52ab-90ab-10aa0a5d1903'::uuid, '0fadcbb8-e482-5c65-939a-99c1ee33c8f3'::uuid), ('ab8f96ef-8d67-5e01-95fe-2f0abe2cd50e'::uuid, 'ca300a66-3e03-5334-a7e7-f87853a93157'::uuid), ('730e799b-a7e3-5599-87fe-7d25b72dead0'::uuid, '87d51b68-0018-5721-9c96-ec9393b3bff7'::uuid), ('e4fa6811-2b2f-54ba-afef-dbb2a8093275'::uuid, 'd291b684-cf0d-59cb-ad64-03db562de34b'::uuid), ('62aba8cb-01d6-5e10-b434-e4f20e26d34c'::uuid, '93bef9d9-c4a4-5fb0-934f-5eebd66d7411'::uuid), ('0d6318dc-8662-5f4a-9f2e-1f2aee38e53a'::uuid, '6f89aba8-26c6-5378-a317-3ed43e408669'::uuid), ('e4c02954-23c2-5db4-8349-acf69d405c27'::uuid, 'b8e8ef31-3cfd-55c2-b974-bd830b667b9b'::uuid), ('9b04cb38-fb57-582a-a633-f4a01eb20555'::uuid, 'd9832602-a629-5ef4-bca2-08305730b5a8'::uuid), ('15c56c6a-2394-503a-8395-ed00ad89fbfd'::uuid, '2091d942-0d57-5843-9da0-9fcaa2293e0e'::uuid), ('86cea934-5306-56f0-bbb6-db291a14b4bf'::uuid, 'a3cf175a-89fb-527a-a6f6-0ef5a6519780'::uuid), ('7c6ad5eb-5c66-5533-9ac2-1ecabc1e7478'::uuid, 'ad937a57-89d5-5e9a-b35c-abfb9a24eced'::uuid), ('0dda343c-b020-59b0-b8fa-ee230b8d0f66'::uuid, 'cd1d1650-1d8e-599a-aacf-2225da08b7c8'::uuid), ('0fc4b4cf-0f95-5ec9-a3bc-d843514d84d4'::uuid, 'af063cd9-f6d2-5b0a-bab4-f1aa6d501c07'::uuid), ('44054166-a6d7-539f-8316-7dcb8032d890'::uuid, 'e29707c9-5dae-5604-93bd-6c777d0ffbd1'::uuid), ('9a369476-b10a-5fd8-a708-7a33d6e84dfd'::uuid, 'd3c6eadd-7612-5806-9e78-523bbc515cfb'::uuid), ('82dd2703-56c4-532d-bc07-bd6b088df57b'::uuid, '7ef897d2-a0d4-5dd9-bd93-d275922b2b19'::uuid), ('d5fdcc9c-faec-5b42-abd3-5026cb477f28'::uuid, '873a1029-cde2-5c69-bad4-bf3f503c2c