  IF n <> 40 THEN RAISE EXCEPTION 'expected 40 seats each held by its named director, got %', n; END IF;

  SELECT count(*) INTO n FROM (VALUES ('f3195e82-9666-5a2c-aa71-b77d98b85e36'::uuid, 'd385364f-5adc-5662-b8e9-b64810ed33e6'::uuid), ('7d5d8326-6dfa-54ec-aae4-023a985c3560'::uuid, '6d28a55c-00f1-50e2-b611-5ec83136b0e3'::uuid), ('a1a0d946-d66e-5654-9d82-0f30076842d6'::uuid, 'c8fe09b8-2d92-5512-843a-334652245540'::uuid), ('b9ae0830-b8e4-5f3c-8bdf-0e90bcd64fa6'::uuid, 'efdbb389-d789-5873-a2ca-2b83c71fe473'::uuid), ('a1ff23fb-dfe2-52ab-90ab-10aa0a5d1903'::uuid, '0fadcbb8-e482-5c65-939a-99c1ee33c8f3'::uuid), ('ab8f96ef-8d67-5e01-95fe-2f0abe2cd50e'::uuid, 'ca300a66-3e03-5334-a7e7-f87853a93157'::uuid), ('730e799b-a7e3-5599-87fe-7d25b72dead0'::uuid, '87d51b68-0018-5721-9c96-ec9393b3bff7'::uuid), ('e4fa6811-2b2f-54ba-afef-dbb2a8093275'::uuid, 'd291b684-cf0d-59cb-ad64-03db562de34b'::uuid), ('62aba8cb-01d6-5e10-b434-e4f20e26d34c'::uuid, '93bef9d9-c4a4-5fb0-934f-5eebd66d7411'::uuid), ('0d6318dc-8662-5f4a-9f2e-1f2aee38e53a'::uuid, '6f89aba8-26c6-5378-a317-3ed43e408669'::uuid), ('e4c02954-23c2-5db4-8349-acf69d405c27'::uuid, 'b8e8ef31-3cfd-55c2-b974-bd830b667b9b'::uuid), ('9b04cb38-fb57-582a-a633-f4a01eb20555'::uuid, 'd9832602-a629-5ef4-bca2-08305730b5a8'::uuid), ('15c56c6a-2394-503a-8395-ed00ad89fbfd'::uuid, '2091d942-0d57-5843-9da0-9fcaa2293e0e'::uuid), ('86cea934-5306-56f0-bbb6-db291a14b4bf'::uuid, 'a3cf175a-89fb-527a-a6f6-0ef5a6519780'::uuid), ('7c6ad5eb-5c66-5533-9ac2-1ecabc1e7478'::uuid, 'ad937a57-89d5-5e9a-b35c-abfb9a24eced'::uuid), ('0dda343c-b020-59b0-b8fa-ee230b8d0f66'::uuid, 'cd1d1650-1d8e-599a-aacf-2225da08b7c8'::uuid), ('0fc4b4cf-0f95-5ec9-a3bc-d843514d84d4'::uuid, 'af063cd9-f6d2-5b0a-bab4-f1aa6d501c07'::uuid), ('44054166-a6d7-539f-8316-7dcb8032d890'::uuid, 'e29707c9-5dae-5604-93bd-6c777d0ffbd1'::uuid), ('9a369476-b10a-5fd8-a708-7a33d6e84dfd'::uuid, 'd3c6eadd-7612-5806-9e78-523bbc515cfb'::uuid), ('82dd2703-56c4-532d-bc07-bd6b088df57b'::uuid, '7ef897d2-a0d4-5dd9-bd93-d275922b2b19'::uuid), ('d5fdcc9c-faec-5b42-abd3-5026cb477f28'::uuid, '873a1029-cde2-5c69-bad4-bf3f503c2cd4'::uuid), ('1e8e4e20-6165-59e0-b7a8-c1e87df54d49'::uuid, 'c48cdfa1-bd1a-594b-b63c-71683b6cd358'::uuid), ('c89743db-7318-5cb3-8a13-120ea82eaea6'::uuid, '253ad3cf-32e5-5a34-a3e2-00d45317f17b'::uuid), ('f748a8c7-29b7-5f42-85da-0272170dcc8a'::uuid, '8f380e12-30e6-50ab-90cb-19cad479c33b'::uuid), ('157c382f-3126-5af8-bd47-9d864cf7c896'::uuid, '04420120-e80f-56cc-ba96-7b241e36bca0'::uuid), ('631c221a-dd0c-52b8-bd3b-052376a21fd2'::uuid, 'ec015b62-3eb9-5d15-a916-e2d9ef636fbd'::uuid), ('b2aeca90-2ff4-5ffe-80b8-600c26cb7218'::uuid, 'd4eea263-27f9-5b4c-a520-89351e000eff'::uuid), ('460a7685-eeae-5428-bf0c-a11dde374cd0'::uuid, '7b961e2e-d09b-56df-9b0b-c734af2e0bcb'::uuid), ('f0b8d24c-7e98-59bb-8375-2294a6c1175f'::uuid, 'e18c2e6e-a096-4043-b5f4-c414401ea08a'::uuid), ('888692ce-14ee-57fb-9565-b6c83efe48ad'::uuid, 'f4ecf9b9-25c7-577d-be15-d7c4608ec871'::uuid), ('f865d391-a85e-5084-92e6-4a1e27b22e34'::uuid, 'efb90f4c-7ec5-51e5-8531-3f71e42d3adc'::uuid), ('6c3a206d-a1be-591c-9a1b-3d25b3661303'::uuid, 'ee381f84-a2b2-4059-8ba2-8a2f5721eab4'::uuid), ('d9ddcadb-6cd1-5bf0-b730-bf6ddcc76ed3'::uuid, 'ed444d27-f39d-53c0-b90e-a7162a564755'::uuid), ('aac0fca2-e2b6-5b90-b391-ac65c2b31d7d'::uuid, '1e4e6adb-0545-5be3-b04b-43d2848d9c48'::uuid), ('efd7e172-33bd-553b-ac98-cd781b8fe0a1'::uuid, '00bf3bf0-55e7-5be2-aa37-4fafcd544621'::uuid), ('ba91c6ad-f1d6-548b-997e-39ab8100e813'::uuid, '881d5e85-2e33-4297-b12e-23c667d61781'::uuid), ('5b24e7be-1318-5cb9-b365-766c147c6b48'::uuid, '4d4f85a7-d6d1-4d78-aa78-cd8070489ba4'::uuid), ('825ff0d5-43a3-5168-9a2a-874794ccdedf'::uuid, '25c2618f-f7bc-5af7-b893-ec5968557104'::uuid), ('154455fa-307b-5154-8268-9a795417c6a4'::uuid, '59b23844-46ec-5224-80aa-a861a55f1f74'::uuid), ('3d02f794-f18e-57cf-9510-697e402050f0'::uuid, '6bb02c38-3f52-5a18-9a4a-e11695ff5dd0'::uuid)) AS v(oid, pid) JOIN essentials.politicians p ON p.id = v.pid
   WHERE p.party IS NOT NULL OR NOT p.is_active OR NOT p.is_incumbent;
  IF n <> 0 THEN RAISE EXCEPTION '% seated director row(s) carry a party or are not active incumbents', n; END IF;

  -- partition: no two divisions of one district overlap beyond ~1,000 m2 (1e-7 deg2 at 34 N; planar, decision 0006)
  SELECT count(*) INTO n FROM essentials.districts a JOIN essentials.districts c ON c.government_id = a.government_id AND a.geo_id < c.geo_id
    JOIN essentials.geofence_boundaries ga ON ga.geo_id = a.geo_id AND ga.mtfcc = 'X-CA-SPD'
    JOIN essentials.geofence_boundaries gc ON gc.geo_id = c.geo_id AND gc.mtfcc = 'X-CA-SPD'
   WHERE a.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid) AND public.ST_Area(public.ST_Intersection(ga.geometry, gc.geometry)) > 1e-7;
  IF n <> 0 THEN RAISE EXCEPTION '% division pair(s) overlap', n; END IF;

  -- END TO END: an interior point of each polygon resolves (geofence -> LOCAL district -> office -> holder)
  -- to exactly that district's own director(s) among this board's seats
  SELECT count(*) INTO n FROM essentials.districts me
    JOIN essentials.geofence_boundaries mg ON mg.geo_id = me.geo_id AND mg.mtfcc = 'X-CA-SPD'
   WHERE me.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid)
     AND (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.geofence_boundaries gb
            JOIN essentials.districts d ON d.geo_id = gb.geo_id AND d.district_type = 'LOCAL' AND d.mtfcc = gb.mtfcc
            JOIN essentials.offices o ON o.district_id = d.id
            JOIN essentials.office_current_holder och ON och.office_id = o.id AND och.politician_id IS NOT NULL
           WHERE d.government_id = me.government_id AND gb.mtfcc = 'X-CA-SPD'
             AND public.ST_Covers(gb.geometry, public.ST_PointOnSurface(mg.geometry)))
         IS DISTINCT FROM
         (SELECT string_agg(och.politician_id::text, ',' ORDER BY och.politician_id)
            FROM essentials.offices o JOIN essentials.office_current_holder och ON och.office_id = o.id
           WHERE o.district_id = me.id AND och.politician_id IS NOT NULL);
  IF n <> 0 THEN RAISE EXCEPTION '% polygon(s) do not return exactly their own director(s) at an interior point', n; END IF;

  SELECT count(*), count(*) FILTER (WHERE r.office_id IS NULL OR r.primary_party IS NOT NULL) INTO n, n2
    FROM essentials.races r JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid);
  IF n <> 12 OR n2 <> 0 THEN RAISE EXCEPTION 'expected 12 office-bound nonpartisan races, got % (% bad)', n, n2; END IF;
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid);
  IF n <> 25 THEN RAISE EXCEPTION 'expected 25 candidates, got %', n; END IF;

  -- every incumbent candidate is linked to a director seated on this board
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races r ON r.id = rc.race_id
    JOIN essentials.offices o ON o.id = r.office_id JOIN essentials.districts d ON d.id = o.district_id
   WHERE r.election_id = 'd91a20ce-557e-4615-a31b-5b2b3df2ed14'::uuid AND d.government_id IN ('f53806e3-a15c-503a-8295-cdf56e70ab87'::uuid, '50211542-ab98-59f5-98aa-40a96173645b'::uuid, 'df92d2ba-ab16-5bf1-99d7-395dd2dde849'::uuid, 'a5373a29-4785-523d-8d70-942a84bb9ddd'::uuid, '4a39f726-799a-5254-95d9-2494f5c9fbb4'::uuid, 'ba374434-8a37-5a7b-86b0-dc419fd1779c'::uuid, '8b1e8b33-ba9e-5ca8-a133-540964dabe8b'::uuid) AND rc.is_incumbent
     AND NOT EXISTS (SELECT 1 FROM essentials.offices o2 JOIN essentials.districts d2 ON d2.id = o2.district_id
                       JOIN essentials.office_current_holder och ON och.office_id = o2.id
                      WHERE d2.government_id = d.government_id AND och.politician_id = rc.politician_id);
  IF n <> 0 THEN RAISE EXCEPTION '% incumbent candidate(s) not linked to a seated director', n; END IF;

  RAISE NOTICE 'CA_0241 applied: 7 boards, 34 polygons, 40 seats (40 held), 12 races, 25 candidates';
END $$;

COMMIT;
